import fs from 'node:fs';import path from 'node:path';import {createHash} from 'node:crypto';import assert from 'node:assert/strict';
import {journalLines} from '../live-paper/journal-lines.mjs';import {createStableScreen,observeStableScreen,stableScreenCandidates,STABLE_SCREEN_POLICY} from '../live-paper/stable-market-screen.mjs';import {validateUniverse} from '../live-paper/breadth.mjs';import {validatePriceObservation} from '../live-paper/market-price-publication.mjs';
const rt=path.join(process.env.LOCALAPPDATA,'SigTradingCup','paper-runtime'),u=JSON.parse(fs.readFileSync('live-paper/price-universe.json')),universe=validateUniverse(u,u.tournamentId),file=path.join(rt,'market-prices.jsonl'),fd=fs.openSync(file,'r'),size=fs.fstatSync(fd).size,tail=Buffer.alloc(Math.min(size,1048576));fs.readSync(fd,tail,0,tail.length,size-tail.length);fs.closeSync(fd);const end=size-tail.length+tail.lastIndexOf(10)+1;assert(end>0);
const screenAfter=Date.now()-STABLE_SCREEN_POLICY.activityMs;let seq=0,previous='',state=createStableScreen(),bytes=0;const h=createHash('sha256');for(const line of journalLines(file,{endByte:end})){const row=JSON.parse(line),{hash,...body}=row;assert.equal(row.sequence,++seq);assert.equal(row.previous,previous);assert.equal(hash,createHash('sha256').update(JSON.stringify(body)).digest('hex'));previous=hash;h.update(line+'\n');bytes+=Buffer.byteLength(line)+1;validatePriceObservation(row.event.snapshot,universe);if(Date.parse(row.at)>=screenAfter)state=observeStableScreen(state,row.event.snapshot,row.at);}
assert.equal(bytes,end);const now=Date.now(),original=JSON.parse(fs.readFileSync(path.join(rt,'stable-maker-cohorts','baal-stable-spread-20261005-v2-live','bank.json'))),candidates=stableScreenCandidates(state,now,{excludedMarketIds:original.legs.map(x=>x.marketId)});
const report={schemaVersion:1,at:new Date(now).toISOString(),claimComment:5996357048,selection:'fixed_stable_window_rank_price_changes_not_fitted_returns',policy:STABLE_SCREEN_POLICY,tournamentId:universe.tournamentId,universeExchanges:universe.exchanges.length,source:{bytes,sha256:h.digest('hex'),sequence:seq,tailHash:previous},screenedMarkets:Object.keys(state.markets).length,candidates,invalidQuotes:state.invalidQuotes,oldScopeExcluded:true,networkRequests:0,executionAuthority:false,profitabilityEstablished:false,limitations:['Indicative quotes lack depth and source timestamps; fresh canonical books still gate every future paper entry.','Price changes are an activity proxy, not trade volume or forecast profitability.','Candidate selection uses past observed prices; a separately named future cohort is needed to measure subsequent outcomes.']};
